sys_script_include.script:
var AMPFmcDynamicFilter = Class.create();
AMPFmcDynamicFilter.prototype = {
    getUserFMCs: function() {
        var userId = gs.getUserID();
        var fmcList = [];
        if (gs.hasRole('x_1831875_amp2_0.super_user')) {
            return '';
        }
        var gr = new GlideRecord('x_1821875_amp2_0_user_fmc_access');
        gr.addQuery('u_user', userId);
        gr.addQuery('u_active ', true);
        gr.addQuery();

        while (gr.next()) {
            fmcList.push(gr.getValue('u_fmc'));

        }
        return fmcList.join(',');
    },

    type: 'AMPFmcDynamicFilter'
};
